  'delveUi.npc.halven.greeting':
    'Relikviář dole se znovu posunul. Po půlnoci slyšíme skrz podlahu zpěv a akolytka Tessa přísahá, že pohřební knihy mění vlastní inkoust. Máš-li dost odvahy, {playerName}, vezmi svíci a sestup. Nevěř každému hlasu, který tam dole uslyšíš. Některé znaly tvoje jméno ještě před tvým narozením.',
  'delveUi.npc.halvenMarsh.greeting':
    'Stopa vedla na sever do bažiny, {playerName}. Pod černou vodou zpívá další relikviář a utopení mrtví odpovídají zvonům. Akolytka Edda zná tohle rákosí lépe než já, drž se blízko její lucerny. Vyber obtížnost a já podržím lano, dokud se nevrátíš.',
