  'editor.tutorial.steps.playtest.title': 'Test hraní',
  'editor.tutorial.steps.save.body':
    'Uložit uloží mapu do tohoto prohlížeče, a když jsi přihlášený, také na server. Export stáhne zálohu JSON a Otevřít obnoví uložené mapy a koncepty.',
  'editor.tutorial.steps.save.title': 'Ulož svou práci',
  'editor.tutorial.steps.stage.body':
    'Toto je tvoje mapa vykreslená skutečným herním enginem. Tažením obíháš kamerou, kolečkem zoomuješ a prostředním tlačítkem nebo Shift+tažením posouváš. Kliknutím na zem s nástrojem upravuješ.',
  'editor.tutorial.steps.stage.title': 'Svět',
  'editor.tutorial.steps.toolbar.body':
    'Tady jsou všechny editační nástroje: štětce tvarování, malba biomu, voda, umisťování prvků, tábory a další. Každý má jednoznakovou zkratku zobrazenou v rohu.',
  'editor.tutorial.steps.toolbar.title': 'Lišta nástrojů',
  'editor.tutorial.steps.viewToggle.body':
    'Přepínej mezi vykresleným 3D světem a symbolickou 2D mapou shora. 2D zobrazení je nejlepší pro přesun značek zón a rámování velkých oblastí.',
