    'Někdo pořád stříhá živé ploty, ačkoliv zahradníka nikdo neviděl už sto let. Dej pozor na bludiště: ono dává pozor i na tebe.',
  'entities.zones.farshore_isle.name': 'Vzdálené pobřeží',
