  'entities.zones.palmreach.welcome':
    'Teplý písek, hlučné ptactvo a džungle, která pohlcuje obzor. Naplavený přístav ti na pláži drží zapálený oheň.',
  'entities.zones.veiled_hollow.name': 'Zahalená kotlina',
