  'guide.footer.blurb':
    'Open-source micro-MMO v klasickém stylu. Plň úkoly, hraj ve skupině a objevuj ručně vystavěný svět přímo v prohlížeči.',
  'guide.footer.playNow': 'Hrát teď',
