  'guide.chooser.heading': 'Najdi svou třídu',
  'guide.chooser.intro':
    'Filtruj podle toho, jak rád hraješ. Každá třída je životaschopná, takže to jen zužuje výběr, neřadí je.',
  'guide.chooser.role': 'Role',
  'guide.chooser.style': 'Styl',
  'guide.chooser.resource': 'Zdroj',
  'guide.chooser.complexity': 'Složitost',
