  'yumi.error.partyTooBig3': 'Ochraňte Yumi 3 na 3 umožňuje skupinu až o třech členech.',
  'yumi.error.partyTooBig5': 'Ochraňte Yumi 5 na 5 umožňuje skupinu až o pěti členech.',
