  'entities.npcs.waywatcher_sorrel.greeting':
    'Sníh za tebou, zlato před tebou. Málokdo projde Zlatotáním dvakrát, tak ať ten přechod stojí za to.',
  'entities.npcs.waywatcher_sorrel.name': 'Hlídač cesty Sorrel',
